namespace RonSijm.FluidHumidifier.Factories.SCN;

public class DataIntegrationFlowFactory(string resourceName = null, Action<Humidifier.SCN.DataIntegrationFlow> factoryAction = null) : ResourceFactory<Humidifier.SCN.DataIntegrationFlow>(resourceName)
{

    internal List<InnerDataIntegrationFlowDataIntegrationFlowSourceFactory> SourcesFactories { get; set; } = [];

    internal InnerDataIntegrationFlowDataIntegrationFlowTransformationFactory TransformationFactory { get; set; }

    internal InnerDataIntegrationFlowDataIntegrationFlowTargetFactory TargetFactory { get; set; }

    protected override Humidifier.SCN.DataIntegrationFlow Create()
    {
        var dataIntegrationFlowResult = CreateDataIntegrationFlow();
        factoryAction?.Invoke(dataIntegrationFlowResult);

        return dataIntegrationFlowResult;
    }

    private Humidifier.SCN.DataIntegrationFlow CreateDataIntegrationFlow()
    {
        var dataIntegrationFlowResult = new Humidifier.SCN.DataIntegrationFlow
        {
            GivenName = InputResourceName,
        };

        return dataIntegrationFlowResult;
    }
    public override void CreateChildren(Humidifier.SCN.DataIntegrationFlow result)
    {
        base.CreateChildren(result);

        result.Sources = SourcesFactories.Any() ? SourcesFactories.Select(x => x.Build()).ToList() : null;
        result.Transformation ??= TransformationFactory?.Build();
        result.Target ??= TargetFactory?.Build();
    }

} // End Of Class

